using System;using System.IO;using System.Text;using System.Collections.Generic;using System.Security.Cryptography;
class Offline70OranBoosterFG110 {
 internal const uint Source=2682571,Material=2682572;
 internal const int ServerCooldownGroup=2110;
 internal static readonly uint[,] Pool=new uint[,] {{2682572,42840,1},{2747157,10000,1},{2747158,10000,1},{2747161,700,1},{2747162,700,1},{2747163,700,1},{2747164,700,1},{2747166,5,1},{2747167,5,1},{2747168,5,1},{2747169,5,1},{2747172,10000,1},{2747173,10000,1},{2747176,700,1},{2747177,700,1},{2747178,700,1},{2747179,700,1},{2747181,5,1},{2747182,5,1},{2747183,5,1},{2747184,5,1},{2747185,4000,1},{2747186,4000,1},{2747187,600,1},{2747188,600,1},{2747189,600,1},{2747190,500,1},{2747191,300,1},{2747192,300,1},{2747193,200,1},{2747194,200,1},{2747195,200,1},{2747196,5,1},{2747197,5,1},{2747198,5,1},{2747199,5,1}};
 internal static uint[] Draw(uint roll){if(roll>=100000)throw new InvalidDataException("Oran roll bounds");uint sum=0;for(int i=0;i<Pool.GetLength(0);i++){sum+=Pool[i,1];if(roll<sum)return new uint[]{Pool[i,0],Pool[i,2]};}throw new InvalidDataException("Oran pool total");}
 internal static uint[] Plan(string receipt){if(String.IsNullOrEmpty(receipt))throw new InvalidDataException("Oran receipt");for(int attempt=0;;attempt++){byte[] h;using(SHA256 sha=SHA256.Create())h=sha.ComputeHash(Encoding.UTF8.GetBytes(receipt+":oran:"+attempt));uint v=BitConverter.ToUInt32(h,0);if(v<4294900000U)return Draw(v%100000);}}
 static bool Outcome(uint[] reward){if(reward==null||reward.Length!=2||reward[1]!=1)return false;for(int i=0;i<Pool.GetLength(0);i++)if(Pool[i,0]==reward[0])return true;return false;}
 static void Reserve(Offline70EconomyState s){bool artifact=false,material=false;for(ushort slot=140;slot<189;slot++)if(Offline70Economy.Find(s,7,slot)==null){artifact=true;break;}foreach(Offline70EconomyEntry e in s.Inventory)if(e.List==0&&e.ItemId==Material&&e.Quantity<1000){material=true;break;}if(!material)for(ushort slot=105;slot<137;slot++)if(Offline70Economy.Find(s,0,slot)==null){material=true;break;}if(!artifact||!material)throw new InvalidDataException("Reserve material and pet-artifact space for every Oran outcome");}
 //2110 is a server-local item cooldown key, not an invented PVF group.
 internal static Offline70EconomyState Open(string path,string receipt,ushort slot,uint[] reward,long utcTicks,out bool duplicate){if(!Outcome(reward)||utcTicks<0||utcTicks>DateTime.MaxValue.Ticks)throw new InvalidDataException("Oran outcome or clock");return Offline70Economy.Apply(path,receipt,"oran-booster",slot+":"+Source+":"+reward[0]+":"+reward[1],delegate(Offline70EconomyState s){Offline70EconomyEntry e=Offline70Economy.Find(s,0,slot);if(e==null||e.ItemId!=Source||e.Quantity<1||s.Level<Offline70Economy.Definition(Source).MinimumLevel)throw new InvalidDataException("Oran source ownership or level");Offline70EconomyCooldown cooldown=null;foreach(Offline70EconomyCooldown c in s.Cooldowns)if(c.Group==ServerCooldownGroup)cooldown=c;long delay=1000L*TimeSpan.TicksPerMillisecond;if(cooldown!=null&&(utcTicks<cooldown.UtcTicks||utcTicks-cooldown.UtcTicks<delay))throw new InvalidDataException("Oran one-second cooldown");Reserve(s);if(e.Quantity==1)s.Inventory.Remove(e);else e.Quantity--;Offline70Economy.AddAssetItem(s,reward[0],1);if(cooldown==null){cooldown=new Offline70EconomyCooldown{Group=ServerCooldownGroup};s.Cooldowns.Add(cooldown);}cooldown.UtcTicks=utcTicks;},out duplicate);}
 internal static byte[] Body(ushort slot,uint[] reward){if(!Outcome(reward))throw new InvalidDataException("Oran reply outcome");using(MemoryStream m=new MemoryStream())using(BinaryWriter w=new BinaryWriter(m)){w.Write((byte)1);w.Write(slot);w.Write(Source);w.Write((uint)1);w.Write((ushort)1);w.Write(reward[0]);w.Write(reward[1]);return m.ToArray();}}
 internal static byte[] Reply(ushort slot,uint[] reward,byte[] keys){return Offline70RoleProtocol.BatchPacketFG(1,175,Body(slot,reward),keys,true);}
}
